params.content:
body {
    font-family: Arial, sans-serif;
    line-height: 1.6;
    margin: 0;
    padding: 0;
    background: #f4f4f4;
}

header {
    background: #333;
    color: #fff;
    text-align: center;
    padding: 1rem;
}

main {
    max-width: 800px;
    margin: 2rem auto;
    background: #fff;
    padding: 1rem;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}

article {
    margin-bottom: 1rem;
}

article h2 {
    color: #333;
}

article p {
    color: #555;
}

article ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

article ul li {
    margin: 0.5rem 0;
}

footer {
    text-align: center;
    padding: 1rem;
    background: #333;
    color: #fff;
}

document.addEventListener('DOMContentLoaded', function() {
    const articles = document.querySelectorAll('article');

    articles.forEach(article => {
        article.addEventListener('click', function() {
            this.classList.toggle('expanded');
        });
    });
});

